WITH flattened AS (SELECT id, customer_id, created_at, code FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) li AS code) SELECT code, DATE_TRUNC('DAY', created_at) AS activity_day, MIN(created_at) AS first_created_at, COUNT(CASE WHEN code = 'WELCOME5' THEN 1 END) AS welcome5_count, COUNT(*) AS event_count, SORT_ARRAY(COLLECT_SET(code)) AS code_list, COUNT(CASE WHEN code = 'SPRING10' THEN 1 END) AS spring10_count FROM flattened GROUP BY code, DATE_TRUNC('DAY', created_at) HAVING welcome5_count > 1;
